src/app.router.ts.source:
/**
 * The root application router. Domains: branches, rooms, staff, sessions,
 * rates (the rate-configuration service), catalogue. Every procedure
 * resolves scope from the verified session claims (Layer 1,
 * spec/multi-tenancy.md §3); tenant identifiers are never authoritative
 * inputs.
 */
import { trpc } from "./trpc";
import { branchesRouter } from "./routers/branches.router";
import { catalogueRouter } from "./routers/catalogue.router";
import { ratesRouter } from "./routers/rates.router";
import { roomsRouter } from "./routers/rooms.router";
import { sessionsRouter } from "./routers/sessions.router";
import { staffRouter } from "./routers/staff.router";

export const appRouter = trpc.router({
  branches: branchesRouter,
  catalogue: catalogueRouter,
  rates: ratesRouter,
  rooms: roomsRouter,
  sessions: sessionsRouter,
  staff: staffRouter,
});

export type AppRouter = typeof appRouter;

src/branch-scope.ts.source:
/**
 * Shared procedure plumbing: turn a claim-derived scope decision into the
 * concrete branch-id filter handed to the data port. The data layer only
 * ever sees claim-scoped branch ids — a client-named branch arrives here
 * only after assertTargetInScope verified it inside the caller's scope.
 */
import { assertTargetInScope, type BranchScopeDecision } from "./scope";
import type { Caller } from "./context";
import type { SilidDataClient } from "./data-client";

export async function resolveBranchIds(
  caller: Caller,
  data: SilidDataClient,
  decision: BranchScopeDecision,
): Promise<string[]> {
  switch (decision.kind) {
    case "branch":
      return [decision.branchId];
    case "target":
      // The lookup runs claim-scoped (RLS-governed); an invisible branch
      // resolves to null and is refused. A resolved branch must still
      // belong to the caller's claim organization.
      return [assertTargetInScope(decision, await data.getBranch(decision.branchId))];
    case "org":
      // Defense in depth: filter the RLS-scoped set to the claim org.
      return (await data.listBranches())
        .filter((branch) => branch.orgId === caller.claims.org_id)
        .map((branch) => branch.id);
    case "platform":
      // The platform tier reaches all organizations by design
      // (spec/multi-tenancy.md §2); its reads are audited and RLS-scoped.
      return (await data.listBranches()).map((branch) => branch.id);
  }
}

src/catalogue.ts.source:
/**
 * The catalogue module (roadmap 04 Deliverable 6): exposes the add-on and
 * canteen catalogues from the MONEY REFERENCE FIXTURE (@silid/db) through
 * typed views, so no client ever hard-codes a price
 * (spec/domain-rules.md §1, §5–§7). Every peso figure here is imported
 * from the fixture — re-typing one anywhere else is a defect proven by the
 * no-re-typed-pesos test.
 */
import { ADDON_CATALOGUE, CANTEEN_CATALOGUE, CANTEEN_CATEGORY_ORDER } from "@silid/db";

export interface AddonCatalogueItem {
  id: string;
  price: number;
  /** Render-only item; only the checkout transaction posts it (vault-09). */
  cashierPostable: boolean;
}

export interface CanteenCatalogueItem {
  id: string;
  label: string;
  price: number;
  category: string;
}

/** The catalogue default prices; a branch's stored overrides take precedence at the database. */
export function defaultAddonCatalogue(): AddonCatalogueItem[] {
  return Object.entries(ADDON_CATALOGUE).map(([id, price]) => ({
    id,
    price,
    cashierPostable: id !== "extension_charge",
  }));
}

/** The full normalized canteen catalogue, ordered by the fixture's category order. */
export function defaultCanteenCatalogue(): CanteenCatalogueItem[] {
  const items = Object.entries(CANTEEN_CATALOGUE).map(([id, item]) => ({
    id,
    label: item.label,
    price: item.price,
    category: item.category,
  }));
  return items.sort(
    (a, b) =>
      CANTEEN_CATEGORY_ORDER.indexOf(a.category as (typeof CANTEEN_CATEGORY_ORDER)[number]) -
        CANTEEN_CATEGORY_ORDER.indexOf(b.category as (typeof CANTEEN_CATEGORY_ORDER)[number]) ||
      a.label.localeCompare(b.label),
  );
}

src/context.ts.source:
/**
 * The tRPC context (Layer 1 wiring). The host application resolves the
 * caller's access token from its session and passes it here; the context
 * factory VERIFIES the token server-side (supabase.auth.getClaims — the
 * JWT-signature-validated path; getSession() is not safe for server
 * guarding, per the Phase 03 research record) and derives the caller's
 * scope claims through @silid/auth's app_metadata readers. The data client
 * runs as the caller, so Row-Level Security governs every query.
 */
import { createClient as createSupabaseClient } from "@supabase/supabase-js";
import { readAppClaims, type AppClaims } from "@silid/auth";
import { createSilidDataClient, type SilidDataClient } from "./data-client";

export interface Caller {
  /** The Supabase Auth user id, from the VERIFIED token's `sub` claim. */
  userId: string;
  /** The app_metadata claim shape (role, org_id, branch_id). */
  claims: AppClaims;
}

export interface TrpcContext {
  /** Null when the request carries no verified session. */
  caller: Caller | null;
  /** Null alongside a null caller; otherwise the as-caller data port. */
  data: SilidDataClient | null;
}

export interface CreateTrpcContextOptions {
  supabaseUrl: string;
  publishableKey: string;
  /** The caller's Supabase access token, resolved by the host app. */
  accessToken: string | null;
}

export async function createTrpcContext(options: CreateTrpcContextOptions): Promise<TrpcContext> {
  const anonymous: TrpcContext = { caller: null, data: null };
  if (options.accessToken === null || options.accessToken === "") {
    return anonymous;
  }

  const authClient = createSupabaseClient(options.supabaseUrl, options.publishableKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await authClient.auth.getClaims(options.accessToken);
  if (error !== null || data === null) {
    return anonymous;
  }
  const claims = readAppClaims(data.claims);
  if (claims === null) {
    return anonymous;
  }
  const sub = (data.claims as Record<string, unknown>).sub;
  if (typeof sub !== "string") {
    return anonymous;
  }

  const asCaller = createSupabaseClient(options.supabaseUrl, options.publishableKey, {
    auth: { persistSession: false, autoRefreshToken: false },
    global: { headers: { Authorization: `Bearer ${options.accessToken}` } },
  });

  return {
    caller: { userId: sub, claims },
    data: createSilidDataClient(asCaller),
  };
}

